import {createChatOrchestrator} from './chatOrchestrator.js';
import type {OrchestratorHooks} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';
const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});
const UNTHROWN = Symbol('unthrown');

const createSession = (): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content: 'hello', timestamp: SENT_AT}],
});

const rejectingProvider = (rejection: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield -- rejects before yielding any chunk
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw rejection;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

const rejectionOf = (call: Promise<unknown>): Promise<unknown> => call.then(() => UNTHROWN, (thrown: unknown) => thrown);

interface ObservedRejection {
  onErrorCount: number;
  isError: boolean;
  causeMatches: boolean;
  callerReceivedOriginal: boolean;
}

const observeRejection = async (rejection: unknown): Promise<ObservedRejection> => {
  const seen: Error[] = [];
  const hooks: OrchestratorHooks = {
    onError: async (_session, error) => {
      seen.push(error);
    },
  };
  const orchestrator = createChatOrchestrator(rejectingProvider(rejection), promptBuilder, undefined, {hooks});
  const caught = await rejectionOf(orchestrator.processMessage(createSession()));
  const [first] = seen;

  return {
    onErrorCount: seen.length,
    isError: first instanceof Error,
    causeMatches: first instanceof Error && Object.is(first.cause, rejection),
    callerReceivedOriginal: Object.is(caught, rejection),
  };
};

describe('ChatOrchestrator onError for non-Error rejections', () => {
  it('wraps a non-Error rejection in an Error whose cause is the original and still rejects the caller with the original', async () => {
    const rejections: unknown[] = ['provider failed', {code: 'E_CUSTOM', detail: 'bad'}, undefined];
    const results = await Promise.all(rejections.map(observeRejection));

    expect(results).toEqual([
      {onErrorCount: 1, isError: true, causeMatches: true, callerReceivedOriginal: true},
      {onErrorCount: 1, isError: true, causeMatches: true, callerReceivedOriginal: true},
      {onErrorCount: 1, isError: true, causeMatches: true, callerReceivedOriginal: true},
    ]);
  });
});

